/*
 * Collapsible code blocks.
 *
 * Wraps the code blocks generated by "code-block" and "literalinclude" into a
 * native <details> element so that long listings can be folded away.
 *
 * A block is folded when the rst source asks for it with the :class: option:
 *
 *     .. literalinclude:: ../domutils/radar_tools/tests/test_radar_tutorial.py
 *        :language: python
 *        :class: collapse-code
 *
 * Setting AUTO_COLLAPSE_LINES below folds every block longer than that many
 * lines instead; :class: no-collapse-code then keeps a given block unfolded.
 *
 * This file lives in docs/_static_custom rather than docs/_static because the
 * latter is erased and repopulated from the zenodo archive at build time, see
 * scripts/download_test_data.sh.
 */

(function () {
    'use strict';

    // Code blocks longer than this get collapsed even when the rst source did
    // not ask for it. Zero disables that, only the blocks carrying the
    // collapse-code class are folded, which keeps the choice a deliberate one.
    var AUTO_COLLAPSE_LINES = 0;

    var FORCE_COLLAPSE = 'collapse-code';
    var NEVER_COLLAPSE = 'no-collapse-code';

    function numberOfLines(wrapper) {
        var pre = wrapper.querySelector('pre');
        if (pre === null) {
            return 0;
        }
        // pygments always terminates the listing with a newline
        return pre.textContent.replace(/\n+$/, '').split('\n').length;
    }

    function shouldCollapse(wrapper, nLines) {
        if (wrapper.classList.contains(NEVER_COLLAPSE)) {
            return false;
        }
        if (wrapper.classList.contains(FORCE_COLLAPSE)) {
            return true;
        }
        return AUTO_COLLAPSE_LINES > 0 && nLines > AUTO_COLLAPSE_LINES;
    }

    // The element to fold away: the caption container when there is one, the
    // highlight wrapper otherwise.
    function containerOf(wrapper) {
        var parent = wrapper.parentElement;
        if (parent !== null && parent.classList.contains('literal-block-wrapper')) {
            return parent;
        }
        return wrapper;
    }

    // Caption text, if the block was given one with the :caption: option.
    function captionOf(container) {
        var caption = container.querySelector(':scope > .code-block-caption');
        if (caption === null) {
            return null;
        }
        var text = caption.querySelector('.caption-text');
        return text === null ? null : text.textContent.trim();
    }

    function labelFor(caption, nLines) {
        var what = (caption === null || caption === '') ? 'code' : caption;
        return what + ' (' + nLines + (nLines === 1 ? ' line)' : ' lines)');
    }

    function updateSummary(summary, label, isOpen) {
        summary.textContent = (isOpen ? 'Hide ' : 'Show ') + label;
    }

    function makeCollapsible(wrapper) {
        var container = containerOf(wrapper);
        if (container.parentElement === null) {
            return;
        }
        // guard against a second pass over an already wrapped block
        if (container.parentElement.classList.contains('collapsible-code')) {
            return;
        }

        var nLines = numberOfLines(wrapper);
        if (!shouldCollapse(wrapper, nLines)) {
            return;
        }

        var label = labelFor(captionOf(container), nLines);

        var details = document.createElement('details');
        details.className = 'collapsible-code';

        var summary = document.createElement('summary');
        updateSummary(summary, label, false);
        details.appendChild(summary);

        container.parentElement.insertBefore(details, container);
        details.appendChild(container);

        details.addEventListener('toggle', function () {
            updateSummary(summary, label, details.open);
        });
    }

    // A link into a collapsed block (permalink, search hit) must not land on
    // something invisible: unfold every <details> on the way to the target.
    function revealTarget() {
        if (!window.location.hash) {
            return;
        }
        var target;
        try {
            target = document.querySelector(window.location.hash);
        } catch (err) {
            return; // not a valid selector
        }
        if (target === null) {
            return;
        }

        var unfolded = false;
        var details = target.closest('details.collapsible-code');
        while (details !== null) {
            if (!details.open) {
                details.open = true;
                unfolded = true;
            }
            details = details.parentElement === null
                ? null
                : details.parentElement.closest('details.collapsible-code');
        }

        // the target moved while unfolding, put it back in view; when nothing
        // was unfolded the browser has already scrolled where it should
        if (unfolded) {
            target.scrollIntoView();
        }
    }

    function init() {
        var highlights = document.querySelectorAll('div.highlight');
        Array.prototype.forEach.call(highlights, function (highlight) {
            // the block sphinx generates is a div.highlight-<language> holding
            // a div.highlight; anything else is not ours to touch
            var wrapper = highlight.parentElement;
            if (wrapper === null || !/(^|\s)highlight-/.test(wrapper.className)) {
                return;
            }
            makeCollapsible(wrapper);
        });
        revealTarget();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    window.addEventListener('hashchange', revealTarget);

    // Unfold everything while printing, a folded block would otherwise be
    // missing from the paper copy.
    var foldedWhilePrinting = [];

    window.addEventListener('beforeprint', function () {
        foldedWhilePrinting = [];
        var all = document.querySelectorAll('details.collapsible-code');
        Array.prototype.forEach.call(all, function (details) {
            if (!details.open) {
                foldedWhilePrinting.push(details);
                details.open = true;
            }
        });
    });

    window.addEventListener('afterprint', function () {
        foldedWhilePrinting.forEach(function (details) {
            details.open = false;
        });
        foldedWhilePrinting = [];
    });
}());
